from complex_quadratic import shape20,reference_gradients # Evaluate the exact fine finite-element displacement interpolation and native integration weights.
GATES={'force_path_relative':.05,'common_free_nodal_u_relative':.05,'bond_slip_area_weighted_relative':.10,'cell_average_stress_relative':.10,'cell_average_peeq_relative':.15} # Freeze research spatial checks before the full refined path is assessed; report all local maxima separately.
def record(name): # Resolve authoritative selected reaction interpretation without altering native data.
    root=q.OUT/'cases'/name;meta=json.loads((root/'metadata.json').read_text());g=dict(np.load(root/'fields.npz'));receipt=json.loads((root/('qualification_v2.json' if (root/'qualification_v2.json').exists() else 'receipt.json')).read_text());m=q.mesh(meta['params'],meta.get('nx',6),meta.get('cross_refinement',1),meta.get('element_type','C3D20R'),meta.get('free_axial_cells'));return root,meta,g,receipt,m # Preserve exact actual topology and constitutive parameters.
def field_at_points(mesh,states,points,material): # Evaluate the complete fine FE displacement field at fixed reference physical locations.
    cells=mesh['elements'];xyz=mesh['xyz'];lower=xyz[cells[:,:8]].min(axis=1);upper=xyz[cells[:,:8]].max(axis=1);ids=[];natural=[] # Use the true quadratic element's rectangular reference geometry.
    for p in points: # Locate each reference observation without averaging unrelated spatial states.
        match=np.where((mesh['materials']==material)&np.all(p>=lower-1.e-8,axis=1)&np.all(p<=upper+1.e-8,axis=1))[0];assert len(match)>0;eid=int(match[0]);ids.append(eid);natural.append(2.*(p-lower[eid])/(upper[eid]-lower[eid])-1.) # Shared-face nodal displacement is continuous, so either adjacent matching solid gives the same value.
    values,_=shape20(np.asarray(natural));return np.einsum('ma,tmai->tmi',values,states[:,cells[np.asarray(ids)],:3]) # Use every actual fine element displacement degree of freedom in the interpolation.
def material_fields_at_points(mesh,graph,points,materials): # Transfer complete native IP fields solely for comparison at identical physical observation points.
    from complex_quadratic import integration_rule # Preserve the exact native quadrature order for both supported integration rules.
    cells=mesh['elements'];xyz=mesh['xyz'];lower=xyz[cells[:,:8]].min(axis=1);upper=xyz[cells[:,:8]].max(axis=1);native,_=integration_rule(mesh['element_type']);levels=np.unique(native[:,0]);result=np.empty((len(graph['states']),len(points),19)) # Retain all six stress and thirteen plastic state components without a global response basis.
    for begin in range(0,len(points),128): # Bound temporary memory while retaining every requested spatial observation.
        part=points[begin:begin+128];ids=[];natural=[] # Locate a true material element for each fixed observation point.
        for location,material in zip(part,materials[begin:begin+128]): # Keep coincident steel/concrete observations independent.
            choices=np.where((mesh['materials']==material)&np.all(location>=lower-1.e-8,axis=1)&np.all(location<=upper+1.e-8,axis=1))[0];assert len(choices)>0;eid=int(choices[0]);ids.append(eid);natural.append(2.*(location-lower[eid])/(upper[eid]-lower[eid])-1.) # Use the undeformed rectangular physical element map.
        natural=np.asarray(natural);weight=np.ones((len(part),len(native))) # Construct tensor-product Lagrange interpolation through all native Gauss values.
        for j,point in enumerate(native): # Preserve complete local IP content rather than replacing it by a cell average.
            for axis in range(3): # Evaluate each independent one-dimensional native Gauss interpolation factor.
                for level in levels: # Form the exact cardinal polynomial corresponding to this native quadrature coordinate.
                    if abs(level-point[axis])>1.e-12: weight[:,j]*=(natural[:,axis]-level)/(point[axis]-level) # Exclude the factor associated with the selected cardinal node itself.
        result[:,begin:begin+len(part)]=np.einsum('mq,tmqd->tmd',weight,graph['states'][:,graph['ip_entity_ids'][np.asarray(ids)],3:22]) # Interpolate all native local components only within their actual fine material cell.
    return result # This comparison transfer never modifies retained native training labels or neural graph entities.
def complete_ip_comparison(coarse_mesh,coarse_graph,fine_mesh,fine_graph): # Compare complete stresses and plastic internal state at every coarse native integration location.
    points=coarse_graph['xyz'][coarse_graph['ip_entity_ids']].reshape(-1,3);material=np.repeat(coarse_mesh['materials'],coarse_graph['ip_entity_ids'].shape[1]);fine=material_fields_at_points(fine_mesh,fine_graph,points,material);coarse=coarse_graph['states'][:,coarse_graph['ip_entity_ids'],3:22].reshape(len(coarse_graph['states']),len(points),19);_,weights=reference_gradients(coarse_mesh['xyz'],coarse_mesh['elements'],element_type=coarse_mesh['element_type']);weights=weights.ravel();observed={} # Use actual reference quadrature measures for the complete time-space field norm.
    for name,channels in [('stress',slice(0,6)),('peeq',slice(6,7)),('plastic_metric',slice(7,13)),('backstress',slice(13,19))]: # Report each physically distinct tensor or scalar state independently.
        selected=np.ones(len(points),bool) if name=='stress' else material==1;reference=fine[:,selected,channels];difference=coarse[:,selected,channels]-reference;denominator=float(np.sum(reference**2*weights[None,selected,None]));observed[name]=float(np.sqrt(np.sum(difference**2*weights[None,selected,None])/max(denominator,1.e-30))) # Exclude nonexistent concrete plastic variables rather than diluting material-state errors.
    return {'observed':observed,'admission_role':'additional_diagnostic_no_new_posthoc_gate','observation_count':len(points),'scope':'Reference-volume-weighted complete tensor/scalar field norms at every actual coarse IP. Fine values use element-local tensor-product Lagrange interpolation through all native Gauss values. Comparison transfer only; no native training field is replaced or reduced.'} # Separate full local-field evidence from the earlier cell-average diagnostics.
def check(coarse='quad_pilot_v2',fine='quad_refine',output_name='mesh_comparison.json'): # Compare the identical actual cyclic path at two genuine quadratic spatial resolutions.
    cr,cm,c,rc,mc=record(coarse);fr,fm,f,rf,mf=record(fine);assert cm['params']==fm['params'];assert cm.get('protocol_id',0)==fm.get('protocol_id',0);assert c['states'].shape[0]==f['states'].shape[0] # Require identical material, geometry dimensions and signed loading history.
    coarse_nodes=mc['real_node_count'];fine_nodes=mf['real_node_count'];cs=set(mc['elements'][mc['materials']==1].ravel());fs=set(mf['elements'][mf['materials']==1].ravel());lookup={(int(i in fs),*np.round(mf['xyz'][i],9)):i for i in range(fine_nodes)};ids=np.array([lookup[(int(i in cs),*np.round(mc['xyz'][i],9))] for i in range(coarse_nodes)]) # Align every real coarse solid node exactly, preserving separate coincident steel/concrete identities.
    u0=c['states'][:,:coarse_nodes,:3];u1=f['states'][:,ids,:3];free=~c['prescribed_mask'][:,:coarse_nodes,:3];u_error=float(np.linalg.norm((u1-u0)[free])/np.linalg.norm(u1[free]));fc=np.array([r['drive_force_N'] for r in rc['checks']]);ff=np.array([r['drive_force_N'] for r in rf['checks']]);force_error=float(np.linalg.norm(ff-fc)/np.linalg.norm(ff)) # Compare actual physical field and full reaction-path errors without prescribed-zero dilution.
    points=mc['xyz'][[a for a,b,area in mc['springs']]];us=field_at_points(mf,f['states'],points,1);uc=field_at_points(mf,f['states'],points,0);fine_slip=us[:,:,0]-uc[:,:,0];coarse_slip=c['states'][:,c['spring_entity_ids'],22];area=np.array([a for i,j,a in mc['springs']]);slip_error=float(np.sqrt(np.sum((fine_slip-coarse_slip)**2*area[None,:])/np.sum(fine_slip**2*area[None,:]))) # Compare all physical bond quadrature observations using the exact fine quadratic displacement field and positive interface area measure.
    _,cw=reference_gradients(mc['xyz'],mc['elements'],element_type=mc['element_type']);_,fw=reference_gradients(mf['xyz'],mf['elements'],element_type=mf['element_type']);cc=mc['xyz'][mc['elements'][:,:8]].mean(axis=1);fl=mf['xyz'][mf['elements'][:,:8]].min(axis=1);fu=mf['xyz'][mf['elements'][:,:8]].max(axis=1);cl=mc['xyz'][mc['elements'][:,:8]].min(axis=1);cu=mc['xyz'][mc['elements'][:,:8]].max(axis=1);parent=[] # Preserve actual reference volume measures for cell-average diagnostics.
    for e in range(len(mf['elements'])): # Assign every refined solid to its unique physical parent cell.
        center=(fl[e]+fu[e])/2.;match=np.where((mc['materials']==mf['materials'][e])&np.all(center>cl-1.e-8,axis=1)&np.all(center<cu+1.e-8,axis=1))[0];assert len(match)==1;parent.append(int(match[0])) # Match material and geometry rather than relying on element numbering.
    parent=np.asarray(parent);cmn=np.einsum('teqd,eq->ted',c['states'][:,c['ip_entity_ids'],3:22],cw)/cw.sum(axis=1)[None,:,None];fine_integrals=np.einsum('teqd,eq->ted',f['states'][:,f['ip_entity_ids'],3:22],fw);fmn=np.zeros_like(cmn) # Compute explicit volume-average diagnostics without replacing any retained training IP values.
    for e,p in enumerate(parent): fmn[:,p,:]+=fine_integrals[:,e,:] # Integrate every child cell into its true parent reference volume.
    fmn/=cw.sum(axis=1)[None,:,None];volume=cw.sum(axis=1);stress_error=float(np.sqrt(np.sum((fmn[:,:,:6]-cmn[:,:,:6])**2*volume[None,:,None])/np.sum(fmn[:,:,:6]**2*volume[None,:,None])));steel=mc['materials']==1;peeq_error=float(np.sqrt(np.sum((fmn[:,steel,6]-cmn[:,steel,6])**2*volume[None,steel])/np.sum(fmn[:,steel,6]**2*volume[None,steel]))) # Separate volume-average stress and plastic strain fidelity from potentially mesh-sensitive local peaks.
    observed={'force_path_relative':force_error,'common_free_nodal_u_relative':u_error,'bond_slip_area_weighted_relative':slip_error,'cell_average_stress_relative':stress_error,'cell_average_peeq_relative':peeq_error};passed=rc['row']['quality']=='VALID_CONVERGED' and rf['row']['quality']=='VALID_CONVERGED' and all(observed[k]<v for k,v in GATES.items());result={'status':'PASS_REGISTERED_SPATIAL_OBSERVABLES' if passed else 'HOLD','coarse':coarse,'fine':fine,'coarse_entities':len(c['xyz']),'fine_entities':len(f['xyz']),'gates':GATES,'observed':observed,'native_qualities':[rc['row']['quality'],rf['row']['quality']],'peak_diagnostics':{'coarse_peeq':float(c['states'][:,c['state_mask'][:,9],9].max()),'fine_peeq':float(f['states'][:,f['state_mask'][:,9],9].max()),'coarse_bond_slip':float(np.max(np.abs(coarse_slip))),'fine_bond_slip_at_same_observation_points':float(np.max(np.abs(fine_slip)))},'scope':'All real coarse solid nodes are exactly shared with the refined model. Bond comparisons evaluate the entire finer quadratic displacement field at every coarse bond Gauss point. Stress and PEEQ comparisons are explicitly cell-volume-average diagnostics; pointwise native IP field convergence is not established by these averages. All native IP fields remain unreduced in training data.','evidence':{'coarse_fields_sha256':q.sha(cr/'fields.npz'),'fine_fields_sha256':q.sha(fr/'fields.npz')}};result['complete_ip_fields']=complete_ip_comparison(mc,c,mf,f);result['status']='PASS_REGISTERED_SPATIAL_OBSERVABLES' if passed else 'HOLD';q.save(q.OUT/'verification'/output_name,result);print(json.dumps(result,indent=2),flush=True);return result # Preserve complete actual values and the precise scope of the fidelity gate.
def element_rank_check(): # Diagnose actual shape-function strain observability without inferring the constrained specimen's failure mechanism.
    from complex_quadratic import NATURAL_NODES # Use the independent native twenty-node reference geometry.
    result={} # Preserve each integration rule's complete singular-value spectrum.
    for kind in ['C3D20R','C3D20']: # Compare eight-point and full twenty-seven-point quadrature on identical nodal degrees of freedom.
        gradient,weights=reference_gradients(NATURAL_NODES,np.arange(20)[None,:],element_type=kind);b=np.zeros((len(weights[0]),6,60)) # Retain every nodal displacement component in the strain map.
        for node in range(20): # Build all six small-strain tensor observations directly from the exact shape gradients.
            dx,dy,dz=gradient[0,:,node].T;b[:,0,3*node]=dx;b[:,1,3*node+1]=dy;b[:,2,3*node+2]=dz;b[:,3,3*node]=dy;b[:,3,3*node+1]=dx;b[:,4,3*node]=dz;b[:,4,3*node+2]=dx;b[:,5,3*node+1]=dz;b[:,5,3*node+2]=dy # Use engineering shear consistently, which does not alter matrix rank.
        matrix=(b*np.sqrt(weights[0,:,None,None])).reshape(-1,60);singular=np.linalg.svd(matrix,compute_uv=False);rank=int(np.sum(singular>singular[0]*1.e-12));result[kind]={'strain_map_shape':list(matrix.shape),'rank':rank,'nullity':60-rank,'rigid_modes':6,'additional_zero_strain_modes':60-rank-6,'singular_values':singular.tolist()} # Distinguish six genuine rigid motions from additional quadrature null directions.
    result['scope']='Independent reference-element small-strain kinematic rank only. This establishes available underintegration null modes, not that the constrained nonlinear specimen occupies them or that all observed displacement errors are hourglassing.';q.save(q.base.OUT/'quadratic/verification/element_kinematic_rank.json',result);return result # Preserve reproducible diagnostic evidence without changing any label or qualification gate.
def time_comparison(coarse='full27_pilot',fine='full27_timehalf'): # Reuse the already registered time-refinement limits on the final full-integration discretization.
    cr,cm,c,rc,mc=record(coarse);fr,fm,f,rf,mf=record(fine);assert cm['params']==fm['params'] and np.array_equal(c['xyz'],f['xyz']) and np.array_equal(c['controls'],f['controls']);force=np.array([s['drive_force_N'] for s in rc['checks']]);reference_force=np.array([s['drive_force_N'] for s in rf['checks']]);force_error=float(np.linalg.norm(force-reference_force)/np.linalg.norm(reference_force));peak=float(c['states'][:,c['state_mask'][:,9],9].max());reference_peak=float(f['states'][:,f['state_mask'][:,9],9].max());peak_error=abs(peak-reference_peak)/reference_peak;diagnostics={} # Compare identical physical controls and native spatial identities without temporal state interpolation.
