        inverse=np.eye(3)-2.*tensor;diagnostics[name]={'minimum_Cp_inverse_eigenvalue':float(np.linalg.eigvalsh(inverse).min()),'maximum_Cp_inverse_determinant_departure':float(np.max(np.abs(np.linalg.det(inverse)-1.)))} # Keep SPD and plastic-volume departure distinct from incomplete constitutive reintegration claims.
