    result={'coarse_case':coarse,'refined_case':fine,'mesh':{'nx':cm.get('nx',6),'cross_refinement':cm.get('cross_refinement',1),'free_axial_cells':cm.get('free_axial_cells',2*cm.get('cross_refinement',1)),'element_type':cm.get('element_type','C3D20R'),'entities':len(c['xyz'])},'status':'PASS' if force_error<.01 and peak_error<.02 and rc['row']['quality']=='VALID_CONVERGED' and rf['row']['quality']=='VALID_CONVERGED' else 'HOLD','original_increment':cm.get('increment',.25),'refined_increment':fm.get('increment',.25),'force_path_relative_L2':force_error,'peak_peeq_relative_change':peak_error,'registered_time_gates':{'force_path_relative_L2':.01,'peak_peeq_relative_change':.02},'additional_native_field_relative_L2':fields,'plastic_metric_diagnostics':diagnostics,'source_fields_sha256':[q.sha(cr/'fields.npz'),q.sha(fr/'fields.npz')]};q.save(q.OUT/'verification/time_comparison.json',result);return result # Preserve the original temporal qualification definition and additional full-state evidence.
